import { useEffect } from 'react';
import type { TelegramWebApp } from './telegram-webapp';

export function useTelegramBackButton(webApp: TelegramWebApp | null, onBack: () => void): void {
  useEffect(() => {
    if (!webApp || !webApp.isVersionAtLeast('6.1')) return;

    const handleClick = () => onBack();
    webApp.BackButton.onClick(handleClick);
    webApp.BackButton.show();

    return () => {
      webApp.BackButton.offClick(handleClick);
      webApp.BackButton.hide();
    };
  }, [webApp, onBack]);
}
