// file: useTelegramMainButton.ts
import { useEffect, useRef } from 'react';
import type { TelegramWebApp } from './telegram-webapp';

interface MainButtonOptions {
  text: string;
  enabled: boolean;
  loading: boolean;
  onClick: () => void;
}

export function useTelegramMainButton(webApp: TelegramWebApp | null, options: MainButtonOptions): void {
  const { text, enabled, loading, onClick } = options;
  const onClickRef = useRef(onClick);
  onClickRef.current = onClick;

  useEffect(() => {
    if (!webApp || !webApp.isVersionAtLeast('6.1')) return;

    const handleClick = () => onClickRef.current();
    webApp.MainButton.onClick(handleClick);
    webApp.MainButton.show();

    return () => {
      webApp.MainButton.offClick(handleClick);
      webApp.MainButton.hide();
    };
  }, [webApp]);

  useEffect(() => {
    if (!webApp || !webApp.isVersionAtLeast('6.1')) return;

    webApp.MainButton.setText(text);

    if (enabled && !loading) {
      webApp.MainButton.enable();
    } else {
      webApp.MainButton.disable();
    }

    if (loading) {
      webApp.MainButton.showProgress(false);
    } else {
      webApp.MainButton.hideProgress();
    }
  }, [webApp, text, enabled, loading]);
}
