import { useEffect } from 'react';
import type { TelegramWebApp } from './telegram-webapp';

export function useClosingConfirmation(webApp: TelegramWebApp | null, isDirty: boolean): void {
  useEffect(() => {
    if (!webApp || !webApp.isVersionAtLeast('6.2')) return;

    if (isDirty) {
      webApp.enableClosingConfirmation();
    } else {
      webApp.disableClosingConfirmation();
    }

    return () => {
      webApp.disableClosingConfirmation();
    };
  }, [webApp, isDirty]);
}
