// file: CheckoutScreen.tsx
import React, { useCallback, useMemo, useState } from 'react';
import { useTelegramWebApp } from './useTelegramWebApp';
import { useTelegramBackButton } from './useTelegramBackButton';
import { useTelegramMainButton } from './useTelegramMainButton';
import { useClosingConfirmation } from './useClosingConfirmation';
import type { CartItem, DeliveryAddress } from './types';
import './CheckoutScreen.css';

export interface CheckoutScreenProps {
  items: CartItem[];
  currency?: string;
  initialAddress?: Partial<DeliveryAddress>;
  onBack: () => void;
  onPay: (address: DeliveryAddress, items: CartItem[]) => Promise<void>;
}

type FieldName = 'fullName' | 'phone' | 'city' | 'street' | 'apartment' | 'postalCode' | 'comment';

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  phone: '',
  city: '',
  street: '',
  apartment: '',
  postalCode: '',
  comment: '',
};

const PHONE_PATTERN = /^[0-9+()\-\s]{6,20}$/;

function validate(address: DeliveryAddress): Partial<Record<FieldName, string>> {
  const errors: Partial<Record<FieldName, string>> = {};
  if (!address.fullName.trim()) errors.fullName = 'Enter your full name';
  if (!address.phone.trim()) {
    errors.phone = 'Enter a phone number';
  } else if (!PHONE_PATTERN.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number';
  }
  if (!address.city.trim()) errors.city = 'Enter a city';
  if (!address.street.trim()) errors.street = 'Enter a street and house number';
  if (!address.postalCode.trim()) errors.postalCode = 'Enter a postal code';
  return errors;
}

function formatMoney(amount: number, currency: string): string {
  try {
    return new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(amount);
  } catch {
    return `${amount.toFixed(2)} ${currency}`;
  }
}

export function CheckoutScreen({
  items,
  currency = 'USD',
  initialAddress,
  onBack,
  onPay,
}: CheckoutScreenProps) {
  const webApp = useTelegramWebApp();

  const [address, setAddress] = useState<DeliveryAddress>({ ...EMPTY_ADDRESS, ...initialAddress });
  const [touched, setTouched] = useState<Partial<Record<FieldName, boolean>>>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const errors = useMemo(() => validate(address), [address]);
  const isValid = Object.keys(errors).length === 0 && items.length > 0;

  const isDirty = useMemo(
    () => Object.values(address).some((value) => value.trim().length > 0),
    [address],
  );

  const total = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items],
  );

  const handleFieldChange = useCallback((field: FieldName, value: string) => {
    setAddress((prev) => ({ ...prev, [field]: value }));
  }, []);

  const handleFieldBlur = useCallback((field: FieldName) => {
    setTouched((prev) => ({ ...prev, [field]: true }));
  }, []);

  const handleBack = useCallback(() => {
    if (!isDirty) {
      onBack();
      return;
    }
    if (webApp) {
      webApp.showConfirm('Discard delivery details and go back to the cart?', (confirmed) => {
        if (confirmed) onBack();
      });
    } else if (window.confirm('Discard delivery details and go back to the cart?')) {
      onBack();
    }
  }, [isDirty, onBack, webApp]);

  const handlePay = useCallback(() => {
    if (submitting) return;

    if (!isValid) {
      setTouched({
        fullName: true,
        phone: true,
        city: true,
        street: true,
        apartment: true,
        postalCode: true,
        comment: true,
      });
      webApp?.HapticFeedback.notificationOccurred('error');
      return;
    }

    setSubmitError(null);
    setSubmitting(true);
    webApp?.HapticFeedback.impactOccurred('medium');

    onPay(address, items)
      .then(() => {
        webApp?.HapticFeedback.notificationOccurred('success');
        webApp?.disableClosingConfirmation();
      })
      .catch((error: unknown) => {
        webApp?.HapticFeedback.notificationOccurred('error');
        const message = error instanceof Error ? error.message : 'Payment failed. Please try again.';
        setSubmitError(message);
        if (webApp) {
          webApp.showAlert(message);
        } else {
          window.alert(message);
        }
      })
      .finally(() => {
        setSubmitting(false);
      });
  }, [address, isValid, items, onPay, submitting, webApp]);

  useTelegramBackButton(webApp, handleBack);
  useTelegramMainButton(webApp, {
    text: submitting ? 'Processing…' : `Pay ${formatMoney(total, currency)}`,
    enabled: isValid,
    loading: submitting,
    onClick: handlePay,
  });
  useClosingConfirmation(webApp, isDirty && !submitting);

  return (
    <div className="checkout-screen">
      <header className="checkout-header">
        <h1 className="checkout-title">Checkout</h1>
      </header>

      <section className="checkout-section" aria-labelledby="order-summary-heading">
        <h2 id="order-summary-heading" className="checkout-section-title">
          Order summary
        </h2>

        {items.length === 0 ? (
          <p className="checkout-empty">Your cart is empty.</p>
        ) : (
          <ul className="checkout-item-list">
            {items.map((item) => (
              <li key={item.id} className="checkout-item">
                <img className="checkout-item-image" src={item.imageUrl} alt={item.title} />
                <div className="checkout-item-info">
                  <span className="checkout-item-title">{item.title}</span>
                  <span className="checkout-item-qty">Qty {item.quantity}</span>
                </div>
                <span className="checkout-item-price">
                  {formatMoney(item.price * item.quantity, currency)}
                </span>
              </li>
            ))}
          </ul>
        )}

        <div className="checkout-total-row">
          <span>Total</span>
          <span>{formatMoney(total, currency)}</span>
        </div>
      </section>

      <section className="checkout-section" aria-labelledby="address-heading">
        <h2 id="address-heading" className="checkout-section-title">
          Delivery address
        </h2>

        <form className="checkout-form" noValidate>
          <div className="checkout-field">
            <label htmlFor="fullName">Full name</label>
            <input
              id="fullName"
              name="fullName"
              type="text"
              autoComplete="name"
              value={address.fullName}
              onChange={(e) => handleFieldChange('fullName', e.target.value)}
              onBlur={() => handleFieldBlur('fullName')}
              aria-invalid={Boolean(touched.fullName && errors.fullName)}
            />
            {touched.fullName && errors.fullName && (
              <span className="checkout-field-error">{errors.fullName}</span>
            )}
          </div>

          <div className="checkout-field">
            <label htmlFor="phone">Phone number</label>
            <input
              id="phone"
              name="phone"
              type="tel"
              autoComplete="tel"
              value={address.phone}
              onChange={(e) => handleFieldChange('phone', e.target.value)}
              onBlur={() => handleFieldBlur('phone')}
              aria-invalid={Boolean(touched.phone && errors.phone)}
            />
            {touched.phone && errors.phone && (
              <span className="checkout-field-error">{errors.phone}</span>
            )}
          </div>

          <div className="checkout-field">
            <label htmlFor="city">City</label>
            <input
              id="city"
              name="city"
              type="text"
              autoComplete="address-level2"
              value={address.city}
              onChange={(e) => handleFieldChange('city', e.target.value)}
              onBlur={() => handleFieldBlur('city')}
              aria-invalid={Boolean(touched.city && errors.city)}
            />
            {touched.city && errors.city && (
              <span className="checkout-field-error">{errors.city}</span>
            )}
          </div>

          <div className="checkout-field">
            <label htmlFor="street">Street and house number</label>
            <input
              id="street"
              name="street"
              type="text"
              autoComplete="address-line1"
              value={address.street}
              onChange={(e) => handleFieldChange('street', e.target.value)}
              onBlur={() => handleFieldBlur('street')}
              aria-invalid={Boolean(touched.street && errors.street)}
            />
            {touched.street && errors.street && (
              <span className="checkout-field-error">{errors.street}</span>
            )}
          </div>

          <div className="checkout-field">
            <label htmlFor="apartment">Apartment / suite (optional)</label>
            <input
              id="apartment"
              name="apartment"
              type="text"
              autoComplete="address-line2"
              value={address.apartment}
              onChange={(e) => handleFieldChange('apartment', e.target.value)}
              onBlur={() => handleFieldBlur('apartment')}
            />
          </div>

          <div className="checkout-field">
            <label htmlFor="postalCode">Postal code</label>
            <input
              id="postalCode"
              name="postalCode"
              type="text"
              autoComplete="postal-code"
              value={address.postalCode}
              onChange={(e) => handleFieldChange('postalCode', e.target.value)}
              onBlur={() => handleFieldBlur('postalCode')}
              aria-invalid={Boolean(touched.postalCode && errors.postalCode)}
            />
            {touched.postalCode && errors.postalCode && (
              <span className="checkout-field-error">{errors.postalCode}</span>
            )}
          </div>

          <div className="checkout-field">
            <label htmlFor="comment">Delivery notes (optional)</label>
            <textarea
              id="comment"
              name="comment"
              rows={3}
              value={address.comment}
              onChange={(e) => handleFieldChange('comment', e.target.value)}
              onBlur={() => handleFieldBlur('comment')}
            />
          </div>
        </form>
      </section>

      {submitError && <p className="checkout-submit-error">{submitError}</p>}

      {/* Pay is Telegram's MainButton (bottom bar) — no in-page Pay button is drawn here. */}
    </div>
  );
}
