Example usage (not required, just shows the wiring):

```tsx
// file: App.tsx (example)
import React, { useState } from 'react';
import { CheckoutScreen } from './CheckoutScreen';
import type { CartItem, DeliveryAddress } from './types';

const sampleItems: CartItem[] = [
  { id: '1', title: 'Wireless Earbuds', imageUrl: '/earbuds.jpg', price: 49.99, quantity: 1 },
  { id: '2', title: 'Phone Case', imageUrl: '/case.jpg', price: 14.5, quantity: 2 },
];

export default function App() {
  const [screen, setScreen] = useState<'cart' | 'checkout'>('checkout');

  if (screen === 'cart') {
    return <div>Cart screen goes here.</div>;
  }

  async function handlePay(address: DeliveryAddress, items: CartItem[]) {
    await fetch('/api/orders', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ address, items }),
    });
  }

  return (
    <CheckoutScreen
      items={sampleItems}
      currency="USD"
      onBack={() => setScreen('cart')}
      onPay={handlePay}
    />
  );
}
